    apps: Object.fromEntries(ALL_APPS.map((a) => [a, CORE_APPS.includes(a)])),
    enabled: Object.fromEntries(SWITCHES.map((k) => [k, k !== "contacts.thoughts" && !WEATHER_EXTRAS.includes(k)])),
    aiPlayerTexts: false,
    inferMissing: false,
    keepTexts: 3,
    keepTrackers: 0,
